messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Low-Poly Humanoid Treadmill Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>

<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const TOTAL_CYCLE_TIME = 10; // seconds
    const STILL_DURATION = 2;
    const WALK_DURATION = 3;
    const RUN_DURATION = 3;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 2, 8); // Side-on view
    camera.lookAt(0, 1.5, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    scene.add(dirLight);

    // --- Materials ---
    const skinMat = new THREE.MeshStandardMaterial({ color: 0xffdab9, roughness: 0.5 });
    const shirtMat = new THREE.MeshStandardMaterial({ color: 0xe74c3c, roughness: 0.5 });
    const pantsMat = new THREE.MeshStandardMaterial({ color: 0x3498db, roughness: 0.5 });
    const shoeMat = new THREE.MeshStandardMaterial({ color: 0x2c3e50, roughness: 0.5 });
    const beltMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.5 });

    // --- Helper: Create Pivot and Mesh ---
    function createLimb(name, geo, mat, parent, pos) {
        const pivot = new THREE.Group();
        pivot.name = name;
        pivot.position.copy(pos);
        const mesh = new THREE.Mesh(geo, mat);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        // Offset mesh so pivot is at the "joint" (top of the limb)
        mesh.position.y = -0.5; // Half height of a unit cylinder
        pivot.add(mesh);
        parent.add(pivot);
        return pivot;
    }

    // --- Build Humanoid ---
    const humanoid = new THREE.Group();
    scene.add(humanoid);

    // 1. Hips (Root of the body)
    const hips = new THREE.Group();
    hips.position.set(0, 1.2, 0);
    humanoid.add(hips);

    // Torso
    const torsoGeo = new THREE.CylinderGeometry(0.25, 0.2, 0.6, 8);
    const torsoPivot = new THREE.Group();
    const torsoMesh = new THREE.Mesh(torsoGeo, shirtMat);
    torsoMesh.position.y = -0.3;
    torsoMesh.castShadow = true;
    torsoPivot.add(torsoMesh);
    hips.add(torsoPivot);

    // Head
    const headGeo = new THREE.SphereGeometry(0.18, 8, 8);
    const headPivot = new THREE.Group();
    const headMesh = new THREE.Mesh(headGeo, skinMat);
    headMesh.position.y = -0.15; // Neck length
    headMesh.castShadow = true;
    headPivot.add(headMesh);
    // Attach head to top of torso
    headPivot.position.set(0, -0.6, 0); // Relative to torsoPivot
    torsoPivot.add(headPivot);

    // Arms
    const armGeo = new THREE.CylinderGeometry(0.06, 0.06, 0.5, 8);
    const leftArm = createLimb('leftArm', armGeo, skinMat, torsoPivot, new THREE.Vector3(0.25, -0.5, 0));
    const rightArm = createLimb('rightArm', armGeo, skinMat, torsoPivot, new THREE.Vector3(-0.25, -0.5, 0));

    // Legs
    const legGeo = new THREE.CylinderGeometry(0.08, 0.06, 0.6, 8);
    const leftLeg = createLimb('leftLeg', legGeo, pantsMat, hips, new THREE.Vector3(0.12, -0.2, 0));
    const rightLeg = createLimb('rightLeg', legGeo, pantsMat, hips, new THREE.Vector3(-0.12, -0.2, 0));

    // Shoes (Children of legs)
    const shoeGeo = new THREE.BoxGeometry(0.1, 0.05, 0.2);
    const leftShoe = new THREE.Mesh(shoeGeo, shoeMat);
    leftShoe.position.set(0, -0.3, 0.05);
    leftShoe.castShadow = true;
    leftLeg.add(leftShoe);

    const rightShoe = new THREE.Mesh(shoeGeo, shoeMat);
    rightShoe.position.set(0, -0.3, 0.05);
    rightShoe.castShadow = true;
    rightLeg.add(rightShoe);

    // --- Treadmill ---
    const treadmillGroup = new THREE.Group();
    scene.add(treadmillGroup);

    // Belt
    const beltGeo = new THREE.PlaneGeometry(3, 1.2);
    const beltMat = new THREE.MeshStandardMaterial({ color: 0x555555, side: THREE.DoubleSide });
    const belt = new THREE.Mesh(beltGeo, beltMat);
    belt.rotation.x = -Math.PI / 2;
    belt.position.y = 0.01;
    belt.receiveShadow = true;
    treadmillGroup.add(belt);

    // Frame
    const frameGeo = new THREE.BoxGeometry(3.2, 0.4, 1.4);
    const frameMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
    const frame = new THREE.Mesh(frameGeo, frameMat);
    frame.position.y = -0.2;
    frame.castShadow = true;
    frame.receiveShadow = true;
    treadmillGroup.add(frame);

    // Rollers
    const rollerGeo = new THREE.CylinderGeometry(0.15, 0.15, 1.4, 16);
    const rollerMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
    const frontRoller = new THREE.Mesh(rollerGeo, rollerMat);
    frontRoller.rotation.z = Math.PI / 2;
    frontRoller.position.set(0, -0.2, 0);
    frontRoller.castShadow = true;
    treadmillGroup.add(frontRoller);

    const backRoller = new THREE.Mesh(rollerGeo, rollerMat);
    backRoller.rotation.z = Math.PI / 2;
    backRoller.position.set(0, -0.2, 0);
    backRoller.castShadow = true;
    treadmillGroup.add(backRoller);

    // --- Animation Logic ---
    const clock = new THREE.Clock();
    let elapsedTotal = 0;

    // Helper: Linear Interpolation
    function lerp(start, end, t) {
        return start + (end - start) * t;
    }

    // Helper: Easing for smoother transitions
    function easeInOutSine(t) {
        return -(Math.cos(Math.PI * t) - 1) / 2;
    }

    function animateHumanoid(time) {
        // Determine Phase
        let phaseTime = time % TOTAL_CYCLE_TIME;
        let phase = '';
        let phaseLocalTime = 0;

        if (phaseTime < STILL_DURATION) {
            phase = 'STILL';
            phaseLocalTime = phaseTime;
        } else if (phaseTime < STILL_DURATION + WALK_DURATION) {
            phase = 'WALK';
            phaseLocalTime = phaseTime - STILL_DURATION;
        } else if (phaseTime < STILL_DURATION + WALK_DURATION + RUN_DURATION) {
            phase = 'RUN';
            phaseLocalTime = phaseTime - STILL_DURATION - WALK_DURATION;
        } else {
            phase = 'STILL'; // Last 2 seconds
            phaseLocalTime = phaseTime - (STILL_DURATION + WALK_DURATION + RUN_DURATION);
        }

        // Reset
        leftLeg.rotation.x = 0;
        rightLeg.rotation.x = 0;
        leftArm.rotation.x = 0;
        rightArm.rotation.x = 0;
        torsoPivot.rotation.x = 0; // Lean
        hips.position.y = 1.2; // Bounce

        if (phase === 'STILL') {
            // Idle breathing
            const breath = Math.sin(time * 2) * 0.05;
            torsoPivot.rotation.x = breath;
            hips.position.y = 1.2 + breath * 0.5;
        }
        else if (phase === 'WALK') {
            // Walk Cycle
            const cycleTime = WALK_DURATION;
            const t = phaseLocalTime / cycleTime;
            const cycles = 3; // How many steps in 3 seconds?
            const phaseAngle = t * cycles * Math.PI * 2;

            // Leg Swing
            const legSwing = Math.sin(phaseAngle) * 0.5;
            leftLeg.rotation.x = legSwing;
            rightLeg.rotation.x = -legSwing;

            // Arm Swing (Opposite to legs)
            const armSwing = Math.sin(phaseAngle) * 0.4;
            leftArm.rotation.x = -armSwing;
            rightArm.rotation.x = armSwing;

            // Slight Bounce
            const bounce = Math.abs(Math.sin(phaseAngle)) * 0.05;
            hips.position.y = 1.2 + bounce;

            // Slight Lean
            torsoPivot.rotation.x = 0.05;
        }
        else if (phase === 'RUN') {
            // Run Cycle
            const cycleTime = RUN_DURATION;
            const t = phaseLocalTime / cycleTime;
            const cycles = 5; // Faster steps
            const phaseAngle = t * cycles * Math.PI * 2;

            // Leg Swing (Larger)
            const legSwing = Math.sin(phaseAngle) * 0.8;
            leftLeg.rotation.x = legSwing;
            rightLeg.rotation.x = -legSwing;

            // Arm Swing (Larger, Opposite to legs)
            const armSwing = Math.sin(phaseAngle) * 0.7;
            leftArm.rotation.x = -armSwing;
            rightArm.rotation.x = armSwing;

            // Larger Bounce
            const bounce = Math.abs(Math.sin(phaseAngle)) * 0.15;
            hips.position.y = 1.2 + bounce;

            // Forward Lean
            torsoPivot.rotation.x = 0.15;
        }
    }

    function animate() {
        requestAnimationFrame(animate);

        const delta = clock.getDelta();
        elapsedTotal += delta;

        // Animate Humanoid
        animateHumanoid(elapsedTotal);

        // Animate Treadmill Belt (Visual rotation of texture or simple rotation of rollers)
        // Since we don't have textures, let's rotate the rollers based on phase
        let speed = 0;
        const currentPhaseTime = elapsedTotal % TOTAL_CYCLE_TIME;

        if (currentPhaseTime >= STILL_DURATION && currentPhaseTime < STILL_DURATION + WALK_DURATION) {
            speed = 0.1; // Walk speed
        } else if (currentPhaseTime >= STILL_DURATION + WALK_DURATION) {
            speed = 0.3; // Run speed
        }

        frontRoller.rotation.x += speed * delta * 10;
        backRoller.rotation.x += speed * delta * 10;

        renderer.render(scene, camera);
    }

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Start
    animate();

</script>
</body>
</html>
```
